import {mapState} from "vuex";
import addAttr from "./addAttr";
import {ruleListApi} from "@/api/product";

export default {
  name: "productAttr",
  components: {addAttr},
  data() {
    return {
      loading: false,
      artFrom: {
        page: 1,
        limit: 10,
        rule_name: "",
      },
      columns4: [
        {
          title: "ID",
          key: "id",
          width: 80,
        },
        {
          title: "分类",
          key: "rule_name",
          minWidth: 150,
        },
        {
          title: "规格名",
          key: "attr_name",
          minWidth: 250,
        },
        {
          title: "规格值",
          slot: "attr_value",
          minWidth: 300,
        },
        {
          title: "操作",
          slot: "action",
          fixed: "right",
          minWidth: 120,
        },
      ],
      tableList: [],
      total: 0,
      ids: "",
      selectionCopy: [],
      display: "none",
      isAll: 0,
      checkBox: false,
    };
  },
  computed: {
    ...mapState("admin/layout", ["isMobile"]),
    ...mapState("admin/order", ["orderChartType"]),
    labelWidth() {
      return this.isMobile ? undefined : 96;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
  },
  created() {
    this.getDataList();
  },
  methods: {
    // 删除
    del(row, tit, num) {
      let delfromData = {
        title: tit,
        num: 0,
        url: `product/product/rule/delete/${row.id}`,
        method: "DELETE",
        ids: '',
      };
      this.$modalSure(delfromData).then((res) => {
        this.$Message.success(res.msg);
        this.getDataList();
      }).catch((res) => {
        this.$Message.error(res.msg);
      });
    },
    addAttr() {
      this.$refs.addattr.ids = 0;
      this.$refs.addattr.modal = true;
    },
    // 编辑
    edit(row) {
      this.$refs.addattr.modal = true;
      this.$refs.addattr.getIofo(row);
    },
    // 列表；
    getDataList() {
      this.loading = true;
      ruleListApi(this.artFrom).then((res) => {
        let data = res.data;
        data.list.forEach(item => {
          item.checkBox = false;
        })
        this.tableList = data.list
        if (this.isAll == 1) {
          this.tableList = data.list.map((item) => {
            item.checkBox = true;
            return item;
          });
        }
        this.total = res.data.count;
        // this.isAll = -1;
        this.loading = false;
      })
          .catch((res) => {
            this.loading = false;
            this.$Message.error(res.msg);
          });
    },
    pageChange(status) {
      this.artFrom.page = status;
      this.getDataList();
    },
    // 表格搜索
    userSearchs() {
      this.artFrom.page = 1;
      this.getDataList();
    },
  },
};
